    "Sposta l'intera conversazione salvata, l'elenco di controllo, gli allegati e i file. Le sessioni e le credenziali del provider rimangono qui. Il thread di destinazione utilizza il cablaggio predefinito di quel computer, senza più accesso di quello di cui dispone questo thread. Non viene eseguito nulla finché non invii il messaggio successivo lì. Puoi cambiarne il modello dopo l'apertura. Questo thread rimane qui, in sola lettura, per il ripristino.",
  'Copy files and local Git history. The source project and chats stay here. A new folder is created on the destination. Worktrees use its configured worktree directory.':
    "Copia file e cronologia Git locale. Il progetto sorgente e le chat rimangono qui. Viene creata una nuova cartella nella destinazione. Gli alberi di lavoro utilizzano la directory dell'albero di lavoro configurata.",
