  'Set up CuaDriver on this runtime host. CuaDriver owns OS permissions; Dovo connects agents through MCP.':
    'Configura CuaDriver su questo host runtime. CuaDriver possiede le autorizzazioni del sistema operativo; Dovo connette gli agenti tramite MCP.',
  'Host executable names or paths, without shell quoting. Agent overrides take precedence. New terminals use these shell settings.':
    "Nomi o percorsi degli eseguibili host, senza virgolette di shell. Le sostituzioni dell'agente hanno la precedenza. I nuovi terminali utilizzano queste impostazioni della shell.",
