  command: 'comando',
  'Shell arguments (one per line)': 'Argomenti della shell (uno per riga)',
  'Automatic shell: {value0}. Default: -l (login shell).':
    'Guscio automatico: {value0}. Predefinito: -l (shell di accesso).',
  'Enable agent computer use on this computer':
    "Abilita l'utilizzo del computer dell'agente su questo computer",
  'Grants writable agents access to this computer’s desktop. Read-only agents are excluded. The user and agents share the desktop and app state.':
    "Concede agli agenti scrivibili l'accesso al desktop di questo computer. Sono esclusi gli agenti di sola lettura. L'utente e gli agenti condividono lo stato del desktop e dell'app.",
  'Leave Cua Driver empty to detect it on this computer’s PATH or in its standard installation folder. Changes apply to new agent turns.':
    'Lascia Cua Driver vuoto per rilevarlo sul PERCORSO di questo computer o nella sua cartella di installazione standard. Le modifiche si applicano ai turni dei nuovi agenti.',
  '1. Install on this computer': '1. Installa su questo computer',
  'Run the official installer on the runtime host, then refresh status. It downloads and installs CuaDriver; no Cua account is required.':
    "Esegui il programma di installazione ufficiale sull'host runtime, quindi aggiorna lo stato. Scarica e installa CuaDriver; non è richiesto alcun account Cua.",
  'Minimal Linux systems need libxi6 and at-spi2-core. GNOME needs Cua’s bundled WinRects helper; see the installation guide.':
    "I sistemi Linux minimi necessitano di libxi6 e at-spi2-core. GNOME ha bisogno dell'helper WinRects in bundle di Cua; consultare la guida all'installazione.",
  'Install and set up Cua Driver': 'Installa e configura il driver Cua',
  'Detect / check Cua Driver': 'Rileva/controlla il driver Cua',
  '2. Permissions & desktop access': '2. Autorizzazioni e accesso al desktop',
  '3. Agent MCP, skills & hooks': '3. Agente MCP, competenze e agganci',
  '4. Computer History (optional preview)': '4. Cronologia computer (anteprima opzionale)',
  'Grant macOS Accessibility and Screen Recording to CuaDriver and accept its relaunch. Test desktop access lists apps without changing them. Daemon controls affect active computer-use sessions.':
    "Concedi l'accessibilità macOS e la registrazione dello schermo a CuaDriver e accetta il suo rilancio. Testa le app degli elenchi di accesso al desktop senza modificarle. I controlli del demone influiscono sulle sessioni attive di utilizzo del computer.",
  'Save the computer-use switch for automatic dovo_cua MCP on new writable turns. No manual MCP registration is needed. Install the optional official skill pack; installation links detected agents on this computer.':
    "Salvare l'interruttore di utilizzo del computer per l'MCP dovo_cua automatico sui nuovi turni scrivibili. Non è necessaria la registrazione MCP manuale. Installa lo skill pack ufficiale opzionale; i collegamenti di installazione hanno rilevato agenti su questo computer.",
  'Opt-in, encrypted, metadata-only history. Enable may restart the daemon. Disable keeps recorded data; pause temporarily stops recording. Unsupported builds report an error. Data stays on the runtime host; View recent history retrieves up to 20 events here.':
    "Cronologia opzionale, crittografata, basata solo sui metadati. Abilita potrebbe riavviare il demone. Disabilita mantiene i dati registrati; la pausa interrompe temporaneamente la registrazione. Le build non supportate segnalano un errore. I dati rimangono sull'host runtime; Visualizza la cronologia recente recupera fino a 20 eventi qui.",
  'Delete recorded Computer History?': 'Eliminare la cronologia del computer registrata?',
  'Delete all recorded history and its encryption key on this computer. This cannot be undone.':
    'Elimina tutta la cronologia registrata e la relativa chiave di crittografia su questo computer. Questa operazione non può essere annullata.',
