  'New commits are available. Keep your question and use the latest revision; selected lines will be cleared.':
    'Sono disponibili nuovi commit. Mantieni la tua domanda e utilizza la revisione più recente; le righe selezionate verranno cancellate.',
  'Use latest revision': "Utilizza l'ultima revisione",
  'New review thread': 'Nuovo thread di recensione',
