  'Memory limit (MB)': 'Limite di memoria (MB)',
  "Runs each new thread's agent, its commands and its terminals in a local Docker or Podman container. Only the checkout and the selected harness login are mounted. Running threads keep their setting.":
    "Esegue l'agente di ogni nuova conversazione, i suoi comandi e i suoi terminali in un container Docker o Podman locale. Vengono montati solo la copia di lavoro e l'accesso dell'agente selezionato. Le conversazioni in corso mantengono la loro impostazione.",
  'Without network access the harness cannot reach its model API unless that API runs inside the sandbox. Package installs and web requests also fail.':
    "Senza accesso alla rete l'agente non può raggiungere la API del suo modello, a meno che quella API non giri nella sandbox. Anche le installazioni di pacchetti e le richieste web non riescono.",
  preparing: 'in preparazione',
  stopped: 'arrestato',
  'A thread can change it before its first message.':
    'Una conversazione può cambiarlo prima del suo primo messaggio.',
  'Full network access. The agent can reach any address the host can.':
    "Accesso completo alla rete. L'agente può raggiungere qualsiasi indirizzo raggiungibile dall'host.",
  'Leave empty for no limit.': 'Lascia vuoto per nessun limite.',
  'Leave empty for the default of {value0} MB.':
    'Lascia vuoto per il valore predefinito di {value0} MB.',
  'This thread runs in a Mise container sandbox.':
    'Questa conversazione gira in una sandbox container Mise.',
  'The agent runs on this computer with your user account.':
    "L'agente gira su questo computer con il tuo account utente.",
  'The agent, its commands and its terminals run in a container. Only this checkout and the harness login are mounted.':
    "L'agente, i suoi comandi e i suoi terminali girano in un container. Vengono montati solo questa copia di lavoro e l'accesso dell'agente.",
  'Holds new work that runs without your message once its estimated cost reaches the limit. This covers Bot follow-ups, Bot routine steps, scheduled messages and child agents. Each thread or Bot counts with its child agents. A routine without a Bot starts a new count on each run. Set its own limits in Monitoring and limits. Your next message or Continue resets the count. Turns without a price also hold work. A running turn always finishes.':
    'Mette in attesa il nuovo lavoro eseguito senza un tuo messaggio quando il costo stimato raggiunge il limite. Vale per i seguiti dei Bot, i passaggi di routine di un Bot, i messaggi pianificati e gli agenti figli. Ogni thread o Bot conta insieme ai suoi agenti figli. Una routine senza Bot inizia un nuovo conteggio a ogni esecuzione. Imposta i suoi limiti in Monitoraggio e limiti. Il tuo prossimo messaggio o Continua azzera il conteggio. Anche i turni senza prezzo mettono il lavoro in attesa. Un turno in corso finisce sempre.',
  'During your request: "{value0}"': 'Durante la tua richiesta: "{value0}"',
  'Git hooks do not run for commits in a sandboxed thread. The agent can change files that hooks run.':
    "Gli hook Git non vengono eseguiti per i commit in un thread con sandbox. L'agente può modificare i file che gli hook eseguono.",
